INSERT INTO "ExamQuestion" ("Id", "Question", "TrueChoice", "ExamId", "ChoiceA", "ChoiceB", "ChoiceC", "ChoiceD", "ChoiceE", "Difficulty", "Explanation", "NegativeMarks", "PositiveMarks", "Section") OVERRIDING SYSTEM VALUE VALUES (1, 'What is the worst-case time complexity of searching for an element in a balanced Binary Search Tree (AVL tree) containing n elements?', 2, 1, 'O(1)', 'O(log n)', 'O(n)', 'O(n log n)', 'O(n^2)', 2, 'In a balanced Binary Search Tree (AVL tree), the height h is strictly bounded by O(log n). Therefore, the worst-case search path from root to leaf visits at most O(log n) nodes.', 1.0, 4.0, 4);
INSERT INTO "ExamQuestion" ("Id", "Question", "TrueChoice", "ExamId", "ChoiceA", "ChoiceB", "ChoiceC", "ChoiceD", "ChoiceE", "Difficulty", "Explanation", "NegativeMarks", "PositiveMarks", "Section") OVERRIDING SYSTEM VALUE VALUES (2, 'Which of the following data structures operates on a Last-In, First-Out (LIFO) basis?', 2, 1, 'Queue', 'Stack', 'Binary Heap', 'Linked List', 'Hash Table', 1, 'A Stack operates strictly under the LIFO (Last-In, First-Out) principle, where the most recently inserted item is the first one popped. In contrast, a Queue is FIFO.', 1.0, 4.0, 4);
INSERT INTO "ExamQuestion" ("Id", "Question", "TrueChoice", "ExamId", "ChoiceA", "ChoiceB", "ChoiceC", "ChoiceD", "ChoiceE", "Difficulty", "Explanation", "NegativeMarks", "PositiveMarks", "Section") OVERRIDING SYSTEM VALUE VALUES (3, 'Which asymptotic notation represents the formal upper bound of an algorithm growth rate?', 3, 1, 'Big Omega (O)', 'Big Theta (T)', 'Big O (O)', 'Little Omega (?)', 'Little Theta (?)', 2, 'Big O notation (O) provides an asymptotic upper bound on the running time of an algorithm, meaning f(n) <= c * g(n) for all n >= n0. Big Omega provides the lower bound.', 1.0, 4.0, 4);
INSERT INTO "ExamQuestion" ("Id", "Question", "TrueChoice", "ExamId", "ChoiceA", "ChoiceB", "ChoiceC", "ChoiceD", "ChoiceE", "Difficulty", "Explanation", "NegativeMarks", "PositiveMarks", "Section") OVERRIDING SYSTEM VALUE VALUES (4, 'What is the time complexity of searching for a key in a hash table with separate chaining in the average case?', 1, 1, 'O(1)', 'O(log n)', 'O(n)', 'O(n log n)', 'O(n^2)', 1, 'With a well-distributed hash function and constant load factor alpha = n/m, the expected number of elements in each chain is O(1), leading to average O(1) lookup time.', 1.0, 4.0, 4);
INSERT INTO "ExamQuestion" ("Id", "Question", "TrueChoice", "ExamId", "ChoiceA", "ChoiceB", "ChoiceC", "ChoiceD", "ChoiceE", "Difficulty", "NegativeMarks", "PositiveMarks", "Section") OVERRIDING SYSTEM VALUE VALUES (5, 'Which algorithm finds the single-source shortest paths in a directed or undirected graph with non-negative edge weights?', 1, 1, 'Dijkstra Algorithm', 'Kruskal Algorithm', 'Prim Algorithm', 'Bellman-Ford Algorithm', 'Floyd-Warshall Algorithm', 0, 0.0, 0.0, 0);
